export const CORRECTIONS = {"exotic--bird-infect--bacterial-chlamydophila-psittaci-psittacosis":[{"severity":"contradicts","lectureSays":"ต้องให้ doxycycline นาน 45 วัน (4-6 สัปดาห์) สำคัญมาก สั้นกว่านี้จะ relapse","evidenceSays":"Compendium of Measures to Control Chlamydia psittaci Infection Among Humans (Psittacosis) and Pet Birds (Avian Chlamydiosis) ฉบับ 2017 (PMID 28891690, doi:10.1647/217-265) ระบุชัดว่าลดระยะเวลาการรักษาในนกลงจากฉบับก่อนหน้า ตัวเลข 45 วันมาจากฉบับ 2005/2010 (ฉบับ 2005 = PMID 15742693) และ Guzman et al. J Avian Med Surg 2010 (PMID 20496604) พบว่า doxycycline 35 mg/kg PO q24h นาน 21 วัน หรือ azithromycin 40 mg/kg PO q48h นาน 21 วัน กำจัดเชื้อได้ในนก cockatiel ที่ติดเชื้อจากการทดลอง ส่วนที่ระบุว่า doxycycline เป็นยาหลักยังคงถูกต้อง","examAdvice":"ตอบ doxycycline 45 วัน ตาม lecture แต่ถ้าข้อสอบให้อธิบายเหตุผล อย่าเขียนยืนยันว่าสั้นกว่านี้ relapse เสมอ","sourceRef":"PMID 28891690 (doi:10.1647/217-265); supporting PMID 20496604, PMID 15742693"}],"exotic--bird-infect--polyomavirus":[{"severity":"contradicts","lectureSays":"วัคซีน avian polyomavirus เชิงพาณิชย์เป็นชนิด recombinant","evidenceSays":"วัคซีน APV ที่ขึ้นทะเบียนกับ USDA เป็นวัคซีนเชื้อตาย (inactivated) ซึ่งมีข้อมูลว่าปลอดภัย กระตุ้นภูมิคุ้มกัน และมีประสิทธิภาพในนกกลุ่ม psittacine หลายชนิดทั้งวัยอ่อนและโตเต็มวัย (PMID 9492926) สอดคล้องกับ Ritchie et al. Vaccine 1996 (PMID 8911004) ที่ประเมิน inactivated APV vaccine ทั้งชนิดมีและไม่มี adjuvant ใน Psittaciformes","examAdvice":"ตอบว่ามีวัคซีนได้เต็มปาก ถ้าถามชนิดให้ตอบ recombinant ตาม lecture แล้วจำไว้ในใจว่าของจริงคือ inactivated","sourceRef":"PMID 9492926; supporting PMID 8911004"}],"exotic--bird-infect--vaccine-availability-summary":[{"severity":"contradicts","lectureSays":"มีวัคซีน avian polyomavirus เชิงพาณิชย์ชนิด recombinant","evidenceSays":"วัคซีน avian polyomavirus ที่ขึ้นทะเบียนกับ USDA และผ่านการประเมิน safety ในนก 1,823 ตัว, immunogenicity 285 ตัว และ efficacy 104 ตัว เป็นวัคซีนเชื้อตาย (inactivated) ไม่ใช่ recombinant (Safety, immunogenicity, and efficacy of an inactivated avian polyomavirus vaccine, PMID 9492926) สอดคล้องกับ Ritchie et al. Vaccine 1996 (PMID 8911004) ที่ประเมิน inactivated APV vaccine ใน Psittaciformes ไม่พบงานใน PubMed ที่รายงานวัคซีน APV แบบ recombinant ในนก psittacine ส่วนข้อความว่ามีวัคซีนใช้ได้จริงยังคงถูกต้อง","examAdvice":"ถ้าถามว่ามีวัคซีนไหมให้ตอบว่ามี ถ้าถามชนิดให้ตอบ recombinant ตาม lecture เพราะผู้สอนตรวจเอง แล้วจำไว้ว่าของจริงคือ inactivated","sourceRef":"PMID 9492926; supporting PMID 8911004"}],"exotic--bird-infect--viral-diseases-top-5-ที่ออกข้อสอบบ่อย":[{"severity":"narrows","lectureSays":"PBFD ให้ intracytoplasmic inclusion และใช้ตำแหน่งของ inclusion เป็นตัวแยกจาก Polyoma ที่เป็น intranuclear","evidenceSays":"Circovirus ให้ botryoid intracytoplasmic inclusion ใน macrophage เป็นลักษณะคลาสสิกจริง (Todd 2004, PMID 14741130) แต่รายงาน PBFD ใน great green macaw ที่ยืนยันด้วย PCR, viral sequencing และ in situ hybridization พบ botryoid inclusion bodies ทั้งแบบ intracytoplasmic และ intranuclear ใน cloacal bursa (PMID 40237412, doi:10.1177/10406387251333410) ตำแหน่ง inclusion เพียงอย่างเดียวจึงไม่ใช่ตัวแยกที่เชื่อถือได้ ทั้งสองโรคใช้ PCR เป็น confirmatory test","examAdvice":"ถ้าข้อสอบถามตำแหน่ง inclusion ของ PBFD ให้ตอบ intracytoplasmic ตาม lecture แต่ถ้าถามวิธียืนยันโรค ให้ตอบ PCR ไม่ใช่ตำแหน่ง inclusion","sourceRef":"PMID 40237412 (doi:10.1177/10406387251333410); supporting PMID 14741130"}],"exotic--bird-noninfect--anesthesia":[{"severity":"narrows","lectureSays":"Isoflurane คือ drug of choice สำหรับการวางยาสลบนก","evidenceSays":"งานเปรียบเทียบ sevoflurane กับ isoflurane ในนก psittacine 10 ตัว พบว่าเวลา extubation, sternal และ standing ไม่ต่างกันอย่างมีนัยสำคัญ และนกที่ฟื้นจาก sevoflurane มี ataxia น้อยกว่า (Sevoflurane anesthesia in psittacines, PMID 10484153) ผู้วิจัยระบุข้อจำกัดเองว่าให้ยาทั้งสองตัวที่ 2% ไม่ได้เทียบที่ MAC เท่ากัน จึงทำให้ sevoflurane ดูเหนี่ยวนำช้ากว่า และกลุ่มตัวอย่างเล็กเพียง 10 ตัว","examAdvice":"ข้อปรนัยให้ตอบ isoflurane ตาม lecture ส่วนข้ออัตนัยเสริมได้ว่า sevoflurane เป็นทางเลือกที่ยอมรับได้","sourceRef":"PMID 10484153"}],"exotic--bird-noninfect--cloacal-papilloma":[{"severity":"contradicts","lectureSays":"Cloacal papilloma สัมพันธ์กับ Herpesvirus ร่วมกับ Papillomavirus","evidenceSays":"การตรวจ mucosal papilloma ใน neotropical parrots พบ psittacid herpesvirus (PsHV) DNA ครบทั้ง 41/41 รอยโรค ทั้ง genotype 1, 2 และ 3 และตรวจไม่พบ papillomavirus DNA เลย (Psittacid herpesviruses associated with mucosal papillomas in neotropical parrots, PMID 15231383, doi:10.1016/j.virol.2004.04.033) ส่วน immunoreactivity ต่อ HPV L1 ในนก hyacinth macaw 1 ตัว ผู้วิจัยสรุปว่าเป็น nonspecific staining ที่โน้ตระบุว่าพบบ่อยใน New World psittacine สอดคล้องกับคำว่า neotropical parrots ในแหล่งนี้ ส่วน acetowhite test และ silver nitrate cauterization ไม่ได้ตรวจสอบจากแหล่งนี้","examAdvice":"ถ้าตัวเลือกมีทั้งสองไวรัส ให้ตอบตาม lecture ว่า herpesvirus ร่วม papillomavirus แต่จำไว้ว่าหลักฐานหนักไปทาง PsHV อย่างเดียว","sourceRef":"PMID 15231383 (doi:10.1016/j.virol.2004.04.033)"}],"exotic--bird-noninfect--nutritional-husbandry-diseases":[{"severity":"narrows","lectureSays":"African grey ที่ชักจาก hypocalcemia ตอบสนองดีต่อ calcium gluconate IV","evidenceSays":"ภาวะชักจาก hypocalcemia พบบ่อยใน Psittacus erithacus ที่มาด้วยอาการทางระบบประสาท โดย plasma calcium ขณะชักมักต่ำกว่า 6.0 mg/dL และสาเหตุพื้นฐานยังไม่ทราบแน่ชัด แต่ case report Magnesium therapy in a hypocalcemic African grey parrot (PMID 22645835, doi:10.1647/2009-021.1) รายงานนกที่ระดับ calcium ยังลดลงต่อเนื่องแม้ให้ calcium และ vitamin A, D, E เต็มที่นาน 4 วัน และหยุดชักหลังได้ magnesium sulfate 20 mg/kg IM เพียงครั้งเดียว","examAdvice":"ตอบ calcium gluconate IV ตาม lecture แต่ถ้าโจทย์เป็นเคสที่ให้ calcium แล้วยังชักอยู่ ให้นึกถึง magnesium","sourceRef":"PMID 22645835 (doi:10.1647/2009-021.1)"}],"exotic--field-vet--case-studies-เจอบ่อยในข้อสอบ":[{"severity":"narrows","lectureSays":"LSD แพร่จากปศุสัตว์เข้าสู่สัตว์ป่าที่ถูกคุกคาม โดยยกกระทิง (gaur) เป็นตัวอย่าง","evidenceSays":"Lumpy skin disease as an emerging infectious disease (PMID 37271510, doi:10.4142/jvs.23016) ระบุว่า large ruminant โดยเฉพาะโคและกระบือบ้านเป็นกลุ่มที่ไวรับมากที่สุด และ wild ruminants อาจทำหน้าที่เป็น potential reservoir ในการแพร่เชื้อ ซึ่งเป็นตัวอย่างความเชื่อมโยงระหว่างระบบการผลิตปศุสัตว์กับสัตว์ป่า แต่ไม่พบเอกสารที่รายงานการติดเชื้อ LSDV ตามธรรมชาติในกระทิงโดยเฉพาะ คำว่า potential ของต้นทางยังคงไว้","examAdvice":"ตอบ gaur ตาม lecture ได้เพราะเป็นตัวอย่างที่ผู้สอนใช้เอง แต่ถ้าเขียนบรรยายให้ใช้คำกว้างว่า wild ruminants อาจเป็น potential reservoir","sourceRef":"PMID 37271510 (doi:10.4142/jvs.23016)"}],"exotic--wildlife-career--eczm-5-specialty-boards":[{"severity":"narrows","lectureSays":"WPH ทำงานกับ free-ranging wildlife ด้าน disease surveillance และ epidemiology โดยมีงานคลินิกน้อย (minimal clinical)","evidenceSays":"ECZM Policies & Procedures Part 1 (2024) ระบุ WPH เป็น discipline-based specialty ที่ดูแลโรคและการจัดการสุขภาพของ free-ranging wildlife ทุก taxon ที่ระดับประชากร (at the population level) ครอบคลุม ecosystem health, conservation medicine และ One Health เอกสารไม่ได้ใช้คำว่า minimal clinical ขณะที่ ZHM ระบุชัดว่ารวม comparative medicine, restraint และ anaesthesia ด้วย ส่วนคำว่า studbook ในโน้ตตรงกับ captive population management ในเอกสารต้นทาง","examAdvice":"ตอบตาม lecture ได้ว่า WPH เน้น field และ population ส่วน ZHM เน้น facility แต่อย่าตอบว่า WPH ไม่แตะงานคลินิกเลย","sourceRef":"European College of Zoological Medicine Policies & Procedures, Part 1 (2024)"}],"exotic--zoo-vet--five-domains-of-animal-welfare":[{"severity":"narrows","lectureSays":"Domain ที่ 4 ของ Five Domains คือ Behaviour หมายถึงการได้แสดงพฤติกรรมตามธรรมชาติ","evidenceSays":"The 2020 Five Domains Model: Including Human-Animal Interactions in Assessments of Animal Welfare (PMID 33066335, doi:10.3390/ani10101870) เปลี่ยนชื่อ domain 4 เป็น Behavioural Interactions และเพิ่มปฏิสัมพันธ์กับมนุษย์เป็นองค์ประกอบใหม่ คู่กับปฏิสัมพันธ์กับสิ่งแวดล้อมและกับสัตว์อื่น ส่วน domain 2 ในฉบับนี้ชื่อ Physical Environment โดย domain 1-4 เป็นปัจจัยที่ก่อ affect ทางลบหรือบวก แล้วนำไปประเมินรวมเป็นภาวะจิตใจที่ domain 5","examAdvice":"ท่องชื่อ 5 domains ตาม lecture ไว้ตอบ แต่ถ้าโจทย์อ้างฉบับ 2020 ให้ตอบ Behavioural Interactions และ Physical Environment","sourceRef":"PMID 33066335 (doi:10.3390/ani10101870)"}],"exotic--zoo-vet--quarantine-protocol":[{"severity":"narrows","lectureSays":"ระยะกักโรคอย่างน้อย 30 วัน ขึ้นกับชนิดสัตว์","evidenceSays":"AZA Accreditation Standards & Related Policies ฉบับ 2026 หมวด 2.7 ไม่ปรากฏตัวเลข 30 วันแล้ว แต่กำหนดให้ใช้ quarantine หรือ risk assessment/mitigation หรือทั้งสองอย่างร่วมกัน เพื่อลดความเสี่ยงการนำโรคเข้าสถาบัน และให้ใช้ quarantine แบบอิงเวลาต่อเมื่อไม่สามารถประเมินและลดความเสี่ยงก่อนการเคลื่อนย้ายได้ ตัวเลข 30 วันจึงเป็นแนวทางเดิมที่ยังอ้างอิงได้ แต่ไม่ใช่ข้อบังคับเดียวในปัจจุบัน","examAdvice":"ตอบ 30 วัน ตาม lecture เพราะผู้สอนออกและตรวจข้อสอบเอง ถ้าเป็นข้อเขียนค่อยเสริมว่ามาตรฐาน AZA ปัจจุบันยอมรับ risk assessment แทนได้","sourceRef":"AZA The Accreditation Standards & Related Policies, 2026, section 2.7"}]};
